import React, { type ComponentProps } from 'react';
import type { RenderLeafProps } from 'slate-react';
import { Link, Text } from '@fiverr-private/typography';
import type { CustomTextElement, RichTextViewerProps } from '../types';

interface RichTextLeafProps {
  attributes: RenderLeafProps['attributes'];
  children: React.ReactNode;
  leaf: CustomTextElement;
  className?: RichTextViewerProps['leafClassName'];
  clearTextFormatters?: RichTextViewerProps['clearTextFormatters'];
  size: RichTextViewerProps['textSize'];
}

type TextProps = ComponentProps<typeof Text>;

const RichTextLeaf = ({ attributes, children, leaf, clearTextFormatters, className, size }: RichTextLeafProps) => {
  let fontWeight: TextProps['fontWeight'], fontStyle: TextProps['fontStyle'], decoration: TextProps['decoration'];

  if (leaf.bold && !clearTextFormatters) {
    fontWeight = 'bold';
  }

  if (leaf.italic && !clearTextFormatters) {
    fontStyle = 'italic';
  }

  if (leaf.underline && !clearTextFormatters) {
    decoration = 'underline';
  }

  if (leaf.lineThrough && !clearTextFormatters) {
    decoration = 'lineThrough';
  }

  if (leaf.url) {
    return (
      <Link
        {...attributes}
        className={className}
        size={size}
        fontWeight={fontWeight}
        fontStyle={fontStyle}
        textAlign="start"
        href={leaf.url}
        target="_blank"
        color="linkSecondary"
      >
        {children}
      </Link>
    );
  }

  return (
    <Text
      {...attributes}
      className={className}
      size={size}
      decoration={decoration}
      fontWeight={fontWeight}
      fontStyle={fontStyle}
      textAlign="start"
      as="span"
    >
      {children}
    </Text>
  );
};

RichTextLeaf.displayName = 'RichTextLeaf';
export default RichTextLeaf;
