import { HTML_TAB_KEY, LT_SEPARATOR, TAB_KEY, U_SEPARATOR } from '../constants';
import type { ParagraphNode, SlateChildren } from './types';

export const handleIndentationSlateToMarkdown = (text: string) => {
    let givenText = text;
    let textResult = '';

    while (givenText.startsWith(TAB_KEY)) {
        textResult += HTML_TAB_KEY;
        givenText = givenText.replace(TAB_KEY, '');
    }
    textResult += givenText;
    return textResult;
};

export const splitSlateTextNode = (node: ParagraphNode) => {
    const nodes: SlateChildren[] = [];
    let nodeText = node?.value || '';
    const uRegex = new RegExp('(?<=\\+)(.*?)(?=\\+)');
    const ltRegex = new RegExp(`(?<=${LT_SEPARATOR})(.*?)(?=${LT_SEPARATOR})`);

    const hasTextSeparator = () => nodeText.match(uRegex) || nodeText.match(ltRegex);

    const pushTextNode = (text: string, field?: string) => {
        if (text.length) {
            if (field) {
                nodes.push({
                    text,
                    [field]: true,
                });
            } else {
                nodes.push({
                    text,
                });
            }
        }
    };

    const updateNodesOnMatch = (separator: string, matchedText: string, field: string) => {
        const textToSearch = `${separator}${matchedText}${separator}`;
        const idx = nodeText.indexOf(textToSearch);
        const newNodeText = nodeText.substring(0, idx);
        pushTextNode(newNodeText);
        pushTextNode(matchedText, field);
        nodeText = nodeText.substring(newNodeText.length + textToSearch.length);
    };

    while (hasTextSeparator()) {
        const matchUnderline = nodeText.match(uRegex);
        const matchLineThrough = nodeText.match(ltRegex);

        if (matchUnderline) {
            updateNodesOnMatch(U_SEPARATOR, matchUnderline[0], 'underline');
        } else if (matchLineThrough) {
            updateNodesOnMatch(LT_SEPARATOR, matchLineThrough[0], 'lineThrough');
        }
    }

    pushTextNode(nodeText);

    return nodes;
};

export const handleTextLineBreaks = (children: SlateChildren[]) => {
    const result: SlateChildren[][] = [];
    let currentChildrenArray: SlateChildren[] = [];

    children.forEach((child) => {
        const texts = child.text.match(/[^\r\n]+/g);
        if (texts) {
            if (texts.length === 1 && texts[0] === child.text) {
                currentChildrenArray.push(child);
            } else {
                let sliceIdx = 0;
                if (texts.length > 1) {
                    currentChildrenArray.push({ ...child, text: texts[0] });
                    sliceIdx = 1;
                }
                if (currentChildrenArray.length) {
                    result.push([...currentChildrenArray]);
                }
                texts.slice(sliceIdx, texts.length - 1).forEach((text) => {
                    result.push([{ ...child, text }]);
                });
                currentChildrenArray = [{ ...child, text: texts[texts.length - 1] }];
            }
        } else if (child.text === '\n') {
            if (currentChildrenArray.length) {
                result.push([...currentChildrenArray]);
            }
            result.push([{ ...child, text: '' }]);
            currentChildrenArray = [];
        } else {
            currentChildrenArray.push(child);
        }
    });

    if (currentChildrenArray.length) {
        result.push([...currentChildrenArray]);
    }

    return result;
};
