import React from 'react';
import type { RenderElementProps } from 'slate-react';
import { ListItem, NumberedList, UnorderedList } from '@fiverr-private/list';
import { Text } from '@fiverr-private/typography';
import type { CustomElement } from '../types';

interface RichTextElementProps {
  attributes: RenderElementProps['attributes'];
  children: React.ReactNode;
  element: CustomElement;
  clearBlockFormatters?: boolean;
}

const RichTextElement = ({ attributes, children, element, clearBlockFormatters }: RichTextElementProps) => {
  if (clearBlockFormatters) {
    return <Text {...attributes}>{children}</Text>;
  }
  switch (element.type) {
    case 'unordered-list':
      return <UnorderedList {...attributes}>{children}</UnorderedList>;
    case 'numbered-list':
      return <NumberedList {...attributes}>{children}</NumberedList>;
    case 'list-item':
      return (
        <ListItem {...attributes}>
          <Text {...attributes}>{children}</Text>
        </ListItem>
      );
    default:
      return <Text {...attributes}>{children}</Text>;
  }
};

RichTextElement.displayName = 'RichTextElement';
export default RichTextElement;
