import type { Descendant } from 'slate';
import { unified } from 'unified';
import markdown from 'remark-parse';
import type { Node } from 'unist';
import { visit } from 'unist-util-visit';
import { isEmpty, isUndefined } from 'lodash';
import type { CustomElement, CustomElementType, CustomChildElement } from '../types';
import type { ListNode, MarkdownToSlateProcessor, ParagraphNode, SlateChildren } from './types';
import { handleTextLineBreaks, splitSlateTextNode } from './utils';

let LOCATED_PARAGRAPHS = {};
let prevElement: Node | null = null;

class MarkdownSlateJsonConverter {
    private readonly markdownToSlateProcessor: MarkdownToSlateProcessor | undefined;

    constructor() {
        function plugin() {
            /* eslint-disable @typescript-eslint/ban-ts-comment */
            // @ts-ignore
            this.Compiler = (node: Node) => MarkdownSlateJsonConverter.markdownToSlate(node);
        }

        this.markdownToSlateProcessor = unified().use(markdown).use(plugin) as MarkdownToSlateProcessor;
    }

    private static markdownToSlate(tree: Node): Descendant[] {
        const slateNodes: Descendant[] = [];
        LOCATED_PARAGRAPHS = {};

        const pushEmptyNode = () => {
            slateNodes.push({
                type: 'paragraph',
                children: [{ text: '' }],
            } as Descendant);
        };

        const handleEmptyNodes = (node: Node) => {
            const prevElementPositionEnd = prevElement?.position?.end;
            if (prevElementPositionEnd && node.position && prevElementPositionEnd.line + 1 < node.position.start.line) {
                const prevElementIsList = prevElement?.type === 'list';
                const expectedLinesDiff = prevElementIsList ? 2 : 1;
                for (let i = 0; i < node.position.start.line - prevElementPositionEnd.line - expectedLinesDiff; i++) {
                    pushEmptyNode();
                }
            }
        };

        visit(tree, (node) => {
            switch (node.type) {
                case 'paragraph':
                    if (!LOCATED_PARAGRAPHS[this.getNodeKey(node)]) {
                        handleEmptyNodes(node);
                        slateNodes.push(...MarkdownSlateJsonConverter.convertParagraphNode(node));
                    }
                    break;
                case 'list':
                    handleEmptyNodes(node);
                    slateNodes.push(MarkdownSlateJsonConverter.convertListNode(node));
                    break;
                case 'thematicBreak':
                    if (node.position) {
                        prevElement = node;
                        pushEmptyNode();
                    }
                    break;
                default:
                    break;
            }
        });

        if (slateNodes.length === 0) {
            pushEmptyNode();
        }

        return slateNodes;
    }

    private static calculateParagraphChildren(
        node: ParagraphNode,
        props: Partial<SlateChildren> = {},
        children: SlateChildren[]
    ) {
        const addTextNode = (child: ParagraphNode, extraProps: Partial<SlateChildren> = {}) => {
            if (child.type === 'link' && child.children?.[0].value) {
                children.push({
                    ...props,
                    ...extraProps,
                    url: child.url,
                    text: child.children[0].value,
                });
            } else {
                const textNodes = splitSlateTextNode(child);
                textNodes.forEach((node) => {
                    children.push({
                        ...props,
                        ...extraProps,
                        ...node,
                    });
                });
            }
        };

        node.children?.forEach((child) => {
            switch (child.type) {
                case 'text':
                    addTextNode(child);
                    break;
                case 'link':
                    addTextNode(child);
                    break;
                case 'emphasis':
                    const valueEmphasis = child.children?.[0].value;
                    const childrenEmphasis = child.children?.[0].children;

                    if (!isUndefined(valueEmphasis) && child.children) {
                        addTextNode(child.children[0], { italic: true });
                    } else if (!isEmpty(childrenEmphasis)) {
                        this.calculateParagraphChildren(child, { ...props, italic: true }, children);
                    }
                    break;
                case 'strong':
                    const valueStrong = child.children?.[0].value;
                    const childrenStrong = child.children?.[0].children;

                    if (!isUndefined(valueStrong) && child.children) {
                        addTextNode(child.children[0], { bold: true });
                    } else if (!isEmpty(childrenStrong)) {
                        return this.calculateParagraphChildren(child, { ...props, bold: true }, children);
                    }
                    break;
                default:
                    break;
            }
        });
    }

    private static getNodeKey = (node: Node) => {
        const { start: s, end: e } = node.position || {};

        if (s && e) {
            return `${s.line}_${s.column}_${s.offset}_${e.line}_${e.column}_${e.offset}`;
        }

        return '';
    };

    private static convertParagraphNode(node: ParagraphNode, props = {}): CustomElement[] {
        const children: SlateChildren[] = [];
        LOCATED_PARAGRAPHS[this.getNodeKey(node)] = true;
        prevElement = node;
        this.calculateParagraphChildren(node, props, children);
        const paragraphsChildren = handleTextLineBreaks(children);

        return paragraphsChildren.map((pChildren) => ({
            type: 'paragraph',
            children: pChildren,
        }));
    }

    private static convertListNode(node: ListNode): CustomElement {
        const children: CustomElement[] = [];

        node.children?.forEach((item) => {
            const listItemChildren: CustomChildElement[] = [];

            item.children?.forEach((child) => {
                if (child.type === 'paragraph') {
                    const pNodes = this.convertParagraphNode(child);
                    pNodes.forEach((pNode) => {
                        listItemChildren.push(...pNode.children);
                    });
                }
            });

            children.push({ type: 'list-item', children: listItemChildren });
        });

        const listType: CustomElementType = node.ordered ? 'numbered-list' : 'unordered-list';

        prevElement = node;

        return { type: listType, children };
    }

    public convert(markdownText: string): Descendant[] {
        if (!this.markdownToSlateProcessor) {
            throw new Error('Markdown to slate processor not initialized');
        }

        return this.markdownToSlateProcessor.processSync(markdownText).result as Descendant[];
    }
}

export default new MarkdownSlateJsonConverter();
